import React, { useState, useEffect, useCallback } from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';
import './UserProfilePage.css';

const UserProfilePage = ({ user: currentUser }) => {
  const { uniqueId } = useParams();
  const [profileUser, setProfileUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [selectedProject, setSelectedProject] = useState(null);
  const [projectFiles, setProjectFiles] = useState([]);
  const [showProjectModal, setShowProjectModal] = useState(false);
  const [loadingFiles, setLoadingFiles] = useState(false);

  useEffect(() => {
    fetchUserProfile();
  }, [uniqueId, fetchUserProfile]);

  const fetchUserProfile = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);
      console.log(`Загрузка профиля пользователя: ${uniqueId}`);

      const response = await axios.get(`/api/users/by-unique-id/${uniqueId}`);
      console.log('Профиль загружен:', response.data);
      setProfileUser(response.data);
    } catch (error) {
      console.error('Error fetching user profile:', error);
      console.error('Response data:', error.response?.data);
      console.error('Status:', error.response?.status);

      if (error.response?.status === 404) {
        setError('Пользователь не найден');
      } else if (error.response?.status === 500) {
        setError('Ошибка сервера. Попробуйте позже.');
      } else {
        setError('Ошибка загрузки профиля');
      }
    } finally {
      setLoading(false);
    }
  }, [uniqueId]);

  const handleProjectClick = async (project) => {
    setSelectedProject(project);
    setShowProjectModal(true);
    setLoadingFiles(true);

    try {
      // Если это собственный профиль, получаем файлы через API
      if (currentUser && currentUser.unique_id === uniqueId) {
        const token = localStorage.getItem('access_token');
        const response = await axios.get(`/api/projects/${project.id}/files`, {
          headers: { 'Authorization': `Bearer ${token}` }
        });
        setProjectFiles(response.data);
      } else {
        // Для чужих профилей показываем только информацию о файлах из проекта
        setProjectFiles(project.files || []);
      }
    } catch (error) {
      console.error('Ошибка загрузки файлов проекта:', error);
      setProjectFiles([]);
    } finally {
      setLoadingFiles(false);
    }
  };

  const handleCloseProjectModal = () => {
    setShowProjectModal(false);
    setSelectedProject(null);
    setProjectFiles([]);
  };

  if (loading) {
    return (
      <div className="user-profile-page">
        <div className="loading">Загрузка профиля...</div>
      </div>
    );
  }

  if (error || !profileUser) {
    return (
      <div className="user-profile-page">
        <div className="error">
          <h2>Пользователь не найден</h2>
          <p>Профиль с таким ID не существует или был удален.</p>
        </div>
      </div>
    );
  }

  const isOwnProfile = currentUser && currentUser.unique_id === uniqueId;

  return (
    <div className="user-profile-page">
      <div className="profile-container">
        <div className="profile-header">
          <div className="profile-avatar">
            {profileUser.nickname ? profileUser.nickname.charAt(0).toUpperCase() : 'U'}
          </div>
          <div className="profile-info">
            <h1 className="profile-name">
              {profileUser.nickname || 'Без имени'}
            </h1>
            <p className="profile-email">{profileUser.email}</p>
            {profileUser.bio && (
              <p className="profile-bio">{profileUser.bio}</p>
            )}
          </div>
        </div>

        <div className="profile-content">
          <div className="profile-section">
            <h2>Проекты</h2>
            {profileUser.projects && profileUser.projects.length > 0 ? (
              <div className="projects-grid">
                {profileUser.projects.map((project) => (
                  <div 
                    key={project.id} 
                    className="project-card clickable"
                    onClick={() => handleProjectClick(project)}
                  >
                    <h3>{project.title}</h3>
                    <p>{project.description || 'Без описания'}</p>
                    <div className="project-meta">
                      <span className="project-files-count">
                        Файлов: {project.files ? project.files.length : 0}
                      </span>
                      <span className="project-date">
                        {new Date(project.created_at).toLocaleDateString()}
                      </span>
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <p className="no-projects">
                {isOwnProfile ? 'У вас пока нет проектов' : 'У пользователя нет проектов'}
              </p>
            )}
          </div>

          {isOwnProfile && (
            <div className="profile-actions">
              <button 
                className="btn btn-primary"
                onClick={() => window.location.href = '/settings'}
              >
                Настройки профиля
              </button>
            </div>
          )}
        </div>
      </div>

      {/* Модальное окно для отображения файлов проекта */}
      {showProjectModal && selectedProject && (
        <div className="project-modal-overlay" onClick={handleCloseProjectModal}>
          <div className="project-modal" onClick={(e) => e.stopPropagation()}>
            <div className="project-modal-header">
              <h2>Файлы проекта: {selectedProject.title}</h2>
              <button className="close-btn" onClick={handleCloseProjectModal}>
                ×
              </button>
            </div>
            <div className="project-modal-content">
              {loadingFiles ? (
                <div className="loading">Загрузка файлов...</div>
              ) : projectFiles.length > 0 ? (
                <div className="files-list">
                  {projectFiles.map((file) => (
                    <div key={file.id} className="file-item">
                      <div className="file-info">
                        <span className="file-name">{file.original_filename}</span>
                        <span className="file-size">
                          {(file.file_size / 1024).toFixed(1)} KB
                        </span>
                        <span className="file-type">{file.content_type}</span>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <p className="no-files">В проекте пока нет файлов</p>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default UserProfilePage;
